    //     Assert.IsNotNull(result.ChargeId);
    // }

    // [TestMethod]
    // [DataRow("tok_visa", 25.50)]
    // [DataRow("tok_mastercard", 99.99)]
    // [DataRow("tok_amex", 0.01)]
    // public async Task ChargeAsync_VariousTokensAndAmounts_Succeeds(
    //     string token, double amountDouble)
    // {
    //     decimal amount = (decimal)amountDouble;
    //     var result = await _gateway.ChargeAsync(token, amount);
    //
    //     Assert.IsTrue(result.Success);
    //     Assert.IsNotNull(result.ChargeId);
    // }

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.ChargeAsync(null!, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.ChargeAsync(string.Empty, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.ChargeAsync("tok_valid", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.ChargeAsync("tok_valid", -5.00m));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – current stub behavior
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_NotImplemented_ThrowsNotImplementedException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.RefundAsync("ch_123"));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – contract tests (uncomment once
    //  RefundAsync is implemented)
    // ──────────────────────────────────────────────

    // [TestMethod]
    // public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    // {
    //     var result = await _gateway.RefundAsync("ch_123");
    //
    //     Assert.IsTrue(result.Success);
    //     Assert.IsNotNull(result.RefundId);
    // }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    // ──────────────────────────────────────────────
    //  Record type tests
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ChargeResult_Properties_AreSetCorrectly()
    {
        var result = new ChargeResult("ch_abc", true);

        Assert.AreEqual("ch_abc", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void ChargeResult_EqualityByValue()
    {
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_1", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void ChargeResult_Inequality_DifferentChargeId()
    {
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_2", true);

        Assert.AreNotEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Properties_AreSetCorrectly()
    {
        var result = new RefundResult("re_xyz", false);

        Assert.AreEqual("re_xyz", result.RefundId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void RefundResult_EqualityByValue()
    {
        var a = new RefundResult("re_1", true);
        var b = new RefundResult("re_1", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Inequality_DifferentSuccess()
    {
        var a = new RefundResult("re_1", true);
        var b = new RefundResult("re_1", false);

        Assert.AreNotEqual(a, b);
    }
}

